command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: LANGE TASTHAARE (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined" || !DSK_FW.Sicht) return ui.notifications.error("Luna sagt 🌙: Framework fehlt oder ist veraltet!");

    const gabenName = "Lange Tasthaare";
    const ahne = "Zerzal";
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("zerzalTasthaare", finalEffektName, "Die übernatürliche Wahrnehmung der Tasthaare verblasst wieder. Die Entdeckungsmodi normalisieren sich.");
    }

    // --- 2. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qsWert = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    // --- 3. BERECHNUNGEN ---
    const reichweite = Number(qsWert); 
    const dauerMinuten = reichweite * 3; 

    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    let alterEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete(); 

    // --- 4. EFFEKT AUF DEN WIRKENDEN ANWENDEN ---
    const angelegteEffekte = await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        duration: { minutes: dauerMinuten },
        description: `Besitzt in ${reichweite} Schritt Umkreis erweiterte Entdeckermodi: Dunkelsicht, Unsichtbares spüren & Erschütterungssinn.`,
        flags: { dsk: { ahne: ahne } }
    }]);

    // --- 5. SICHT ÜBER FRAMEWORK MODIFIZIEREN ---
    if (angelegteEffekte && angelegteEffekte.length > 0) {
        const idDunkelsicht = DSK_FW.Sicht.GetDunkelsichtId();

        // Block 15 aus dem Framework übernimmt hier die komplette Arbeit!
        await DSK_FW.Sicht.Modifiziere(casterActor, angelegteEffekte[0], [
            { id: idDunkelsicht, range: reichweite },
            { id: "feelTremor", range: reichweite },
            { id: "senseInvisibility", range: reichweite }
        ]);
    }

    // --- 6. CHAT NACHRICHT GENERIEREN ---
    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    const successContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>${casterName}</b> sträubt die Tasthaare und nimmt feinste Strömungen wahr.</p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="margin-bottom: 8px;">
                    Das Zerzalkind kann seine Umgebung in einem Umkreis von <b>${reichweite} Schritt</b> tastend wahrnehmen, ohne sie zu berühren. Es kann sich so auch in völliger Dunkelheit orientieren.
                </p>
                <div style="background:rgba(0,0,0,0.05); border:1px solid #a89f91; padding:6px; border-radius:3px; margin-bottom: 8px;">
                    <p style="font-weight:bold; color:#333; margin-bottom:5px;">Aktivierte Entdeckermodi:</p>
                    <p style="font-size:0.9em; margin:0;">
                        • Dunkelsicht (Stufe 3)<br>
                        • Erschütterung spüren<br>
                        • Unsichtbares spüren
                    </p>
                </div>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${dauerMinuten} Minuten <span ${thinStyle}>(${qsWert} QS x 3)</span></p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: successContent }); 
    } else {
        await ChatMessage.create({ content: successContent, speaker: { alias: "System" } });
    }
})();
